CREATE TABLE IF NOT EXISTS reserva_inventario (clave VARCHAR(36) PRIMARY KEY,solicitud LONGTEXT NOT NULL,respuesta LONGTEXT);
CREATE TABLE IF NOT EXISTS favorito(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NOT NULL,producto_id BIGINT NOT NULL,fecha TIMESTAMP NOT NULL,UNIQUE KEY(usuario_id,producto_id));
CREATE TABLE IF NOT EXISTS resena(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NOT NULL,producto_id BIGINT NOT NULL,autor VARCHAR(80) NOT NULL,puntuacion INT NOT NULL,comentario VARCHAR(500) NOT NULL,fecha TIMESTAMP NOT NULL,UNIQUE KEY(usuario_id,producto_id));
